// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 _val) internal {
        bool pre_reverted;
        try c.SetMinSum(_val) { pre_reverted = false; } catch { pre_reverted = true; }
        try c.Initialized() {} catch { return; }
        bool post_reverted;
        try c.SetMinSum(_val) { post_reverted = false; } catch { post_reverted = true; }
        bool log_reverted;
        try c.SetLogFile(address(this)) { log_reverted = false; } catch { log_reverted = true; }
        assertTrue(!pre_reverted && post_reverted && log_reverted && c.MinSum() == _val);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
